3. Реализация змейки

Следующим шагом будет реализация змейки. Вам потребуется создать структуру для хранения информации о змейке, которая будет содержать данные о ее положении, длине, скорости и т. Д.

Вот пример структуры для змейки:

```c
#include <vector>

struct Point {
    int x, y;
};

struct Snake {
    std::vector<Point> body;
    int length;
    int direction;
    float speed;

    Snake(int width, int height) :
        body({ { width / 2, height / 2 } }),
        length(1),
        direction(0),
        speed(2.0f) {}

    void handleEvent(SDL_Event& e) {
        if (e.type == SDL_KEYDOWN) {
            int key = e.key.keysym.sym;
            if (key == SDLK_LEFT && direction != 1) {
                direction = 0;
            }
            else if (key == SDLK_RIGHT && direction != 0) {
                direction = 1;
            }
        }
    }

    void update() {
        Point head = body.back();
        int nx = head.x;
        int ny = head.y;

        if (direction == 0) {
            nx--;
        }
        else if (direction == 1) {
            nx++;
        }

        if (nx < 0 || nx >= WINDOW_WIDTH || ny < 0 || ny >= WINDOW_HEIGHT) {
            return;
        }

        body.pop_back();
        body.insert(body.begin(), Point(nx, ny));
    }

    void render() {
        for (const auto& p : body) {
            glBindTexture(GL_TEXTURE_2D, snakeTexture.id);
            glBegin(GL_QUADS);
            glVertex2f(p.x, p.y);
            glVertex2f(p.x + 10, p.y);
            glVertex2f(p.x + 10, p.y + 10);
            glVertex2f(p.x, p.y + 10);
            glEnd();
        }
    }
};
```

